import * as T from './three.module.js';
// Shared geometry and instancing keep the detailed vegetation inexpensive to draw.
export function createForest(scene, random) {
 const rnd=random, dummy=new T.Object3D(), up=new T.Vector3(0,1,0);
 function texture(kind){const c=document.createElement('canvas');c.width=c.height=256;const x=c.getContext('2d');x.fillStyle=kind==='bark'?'#685847':'#8b9081';x.fillRect(0,0,256,256);for(let i=0;i<2800;i++){let v=40+rnd()*100;x.strokeStyle=`rgba(${v},${v*.92},${v*.7},${.1+rnd()*.35})`;x.lineWidth=.5+rnd()*2;x.beginPath();let px=rnd()*256,py=rnd()*256;x.moveTo(px,py);x.lineTo(px+(kind==='bark'?rnd()*5:rnd()*18),py+(kind==='bark'?10+rnd()*70:rnd()*12));x.stroke()}const t=new T.CanvasTexture(c);t.wrapS=t.wrapT=T.RepeatWrapping;return t}
 const barkMap=texture('bark'),stoneMap=texture('stone');
 const bark=new T.MeshStandardMaterial({color:'#918474',map:barkMap,bumpMap:barkMap,bumpScale:.22,roughness:1});
 const stone=new T.MeshStandardMaterial({color:'#859382',map:stoneMap,bumpMap:stoneMap,bumpScale:.3,roughness:1});
 const leafShape=new T.Shape();leafShape.moveTo(0,0);leafShape.bezierCurveTo(-.55,.3,-.42,.8,0,1.3);leafShape.bezierCurveTo(.42,.8,.55,.3,0,0);
 const leafGeo=new T.ShapeGeometry(leafShape,5);leafGeo.rotateX(-Math.PI/2);
 const leafMat=new T.MeshStandardMaterial({color:'#d2dcb5',roughness:.88,side:T.DoubleSide});
 const time={value:0},sound={value:0};leafMat.onBeforeCompile=shader=>{shader.uniforms.forestTime=time;shader.uniforms.forestSound=sound;shader.vertexShader='uniform float forestTime; uniform float forestSound;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\n transformed.y += sin(forestTime * 0.8 + instanceMatrix[3].x * 0.41 + instanceMatrix[3].z * 0.27 + position.z * 2.0) * (0.055 + forestSound * 0.22) * abs(position.z);')};
 const leaves=new T.InstancedMesh(leafGeo,leafMat,200000);leaves.count=0;scene.add(leaves);
 const branches=new T.InstancedMesh(new T.CylinderGeometry(1,1,1,7),bark,24000);branches.count=0;scene.add(branches);
 const stones=new T.InstancedMesh(new T.IcosahedronGeometry(1,1),stone,1400);stones.count=0;scene.add(stones);
 function instance(batch,pos,scale,rotation,color){if(batch.count>=batch.instanceMatrix.count)return;dummy.position.copy(pos);dummy.scale.copy(scale);dummy.rotation.set(...rotation);dummy.updateMatrix();batch.setMatrixAt(batch.count,dummy.matrix);if(color)batch.setColorAt(batch.count,new T.Color(color));batch.count++}
 function twig(a,b,r){const d=b.clone().sub(a);dummy.position.copy(a).add(b).multiplyScalar(.5);dummy.scale.set(r,d.length(),r*.85);dummy.quaternion.setFromUnitVectors(up,d.normalize());dummy.updateMatrix();branches.setMatrixAt(branches.count++,dummy.matrix)}
 function blade(p,s,ry,tilt=0,col='#6c914a'){instance(leaves,p,new T.Vector3(s*.65,s,s),[tilt,ry,(rnd()-.5)*.6],col)}
 function crown(p,r){for(let i=0;i<340;i++){const a=rnd()*Math.PI*2,rr=Math.sqrt(rnd())*r;let v=new T.Vector3(p.x+Math.cos(a)*rr,p.y+(rnd()-.5)*r*.75,p.z+Math.sin(a)*rr);blade(v,.65+rnd()*.85,rnd()*6.28,(rnd()-.5)*1.2,['#335a3d','#527b45','#789754','#91a961'][i%4])}}
 function tree(a,r,h=18){const base=new T.Vector3(Math.cos(a)*r,-1,Math.sin(a)*r),lean=new T.Vector3((rnd()-.5)*3,0,(rnd()-.5)*3);let prev=base.clone();for(let i=1;i<=5;i++){const next=base.clone().add(new T.Vector3(lean.x*i/5,h*i/5,lean.z*i/5));twig(prev,next,(1-i*.14)*h*.052);prev=next}for(let j=0;j<7;j++){const az=j*2.4+rnd(),level=.52+rnd()*.35,start=base.clone().add(new T.Vector3(lean.x*level,h*level,lean.z*level)),end=start.clone().add(new T.Vector3(Math.cos(az)*h*.23,h*.12,Math.sin(az)*h*.23));twig(start,end,.2);const tip=end.clone().add(new T.Vector3(Math.cos(az)*2,2+rnd()*2,Math.sin(az)*2));twig(end,tip,.08);crown(tip,2.7+rnd()*1.5)}for(let j=0;j<6;j++){const a=j*1.047;twig(base.clone().add(new T.Vector3(0,1.7,0)),base.clone().add(new T.Vector3(Math.cos(a)*2.7,.1,Math.sin(a)*2.7)),.27)}}
 function palm(a,r,s=1){const base=new T.Vector3(Math.cos(a)*r,-1,Math.sin(a)*r),top=base.clone().add(new T.Vector3(s*1.1,10*s,0));let prev=base;for(let j=1;j<=7;j++){const next=base.clone().lerp(top,j/7);next.x+=Math.sin(j/7*Math.PI)*s*.6;twig(prev,next,(.34-j*.025)*s);prev=next}for(let j=0;j<9;j++){let az=j*Math.PI*2/9+rnd()*.15,prev=top.clone();for(let k=1;k<=10;k++){let t=k/10,end=top.clone().add(new T.Vector3(Math.cos(az)*t*5*s,(Math.sin(t*Math.PI)*1.2-t*t*2)*s,Math.sin(az)*t*5*s));twig(prev,end,.027*s);for(const side of [-1,1])blade(end,.9*s*(1-t*.65),-az+side*1.1,.3+t*.65,'#527a45');prev=end}}}
 function fern(x,z,s=1){const base=new T.Vector3(x,-.7,z);for(let j=0;j<7;j++){let az=j*.897;for(let k=0;k<7;k++){let t=k/7,p=base.clone().add(new T.Vector3(Math.cos(az)*t*s,Math.sin(t*Math.PI)*s+.2,Math.sin(az)*t*s));for(const side of [-1,1])blade(p,(1-t)*s*.45+.08,-az+side*.9,.25,'#658c48')}}}
 function rock(x,z,s){instance(stones,new T.Vector3(x,-.6,z),new T.Vector3(s,s*.55,s*.8),[rnd(),rnd()*6,rnd()],rnd()>.5?'#7a8c63':'#67766b')}
 function finish(){for(const batch of [leaves,branches,stones]){batch.instanceMatrix.needsUpdate=true;if(batch.instanceColor)batch.instanceColor.needsUpdate=true;batch.computeBoundingSphere()}return {leaves:leaves.count,branches:branches.count,stones:stones.count}}
 return {tree,palm,fern,rock,finish,stone,bark,tick:(t,e)=>{time.value=t;sound.value=e}};
}
